const source = $json.body ?? $json;
const text = (value) => String(value ?? '').trim();
const normalizePhone = (value) => {
  let digits = text(value).replace(/\D/g, '');
  if (digits.startsWith('0')) digits = `62${digits.slice(1)}`;
  if (!digits.startsWith('62')) digits = `62${digits}`;
  return digits;
};
const safe = (value) => text(value).replace(/#/g, '-').replace(/\s+/g, ' ');
const stage = ['tes','wsl1','promotor'].includes(text(source.funnel_stage).toLowerCase()) ? text(source.funnel_stage).toLowerCase() : 'tes';
const campaignMap = { tes: Number($json.campaign_id_test || 0), wsl1: Number($json.campaign_id_wsl1 || 0), promotor: Number($json.campaign_id_promotor || 0) };
const lead = {
  lead_id: text(source.lead_id) || `lead-${Date.now()}`,
  funnel_stage: stage,
  lead_source: safe(source.lead_source || source.utm_source || 'website'),
  name: safe(source.name),
  phone: normalizePhone(source.phone),
  city: safe(source.city),
  need: safe(source.need),
  participant_count: safe(source.participant_count || '1'),
  stifin_result: safe(source.stifin_result),
  learning_goal: safe(source.learning_goal),
  main_question: safe(source.main_question),
  profession: safe(source.profession),
  stifin_status: safe(source.stifin_status),
  wsl_status: safe(source.wsl_status),
  network: safe(source.network),
  promoter_goal: safe(source.promoter_goal),
  promoter_readiness: safe(source.promoter_readiness),
  consent: text(source.consent).toLowerCase(),
  consent_at: text(source.consent_at),
  submitted_at: text(source.submitted_at),
  source_page: text(source.source_page),
  landing_variant: text(source.landing_variant || 'utama'),
  utm_source: text(source.utm_source),
  utm_medium: text(source.utm_medium),
  utm_campaign: text(source.utm_campaign),
  utm_content: text(source.utm_content),
  utm_term: text(source.utm_term),
  fbclid: text(source.fbclid),
  gclid: text(source.gclid),
  campaign_id: campaignMap[stage],
};
if (!lead.name || !lead.city) throw new Error('Nama dan kota wajib diisi.');
if (!/^62\d{8,15}$/.test(lead.phone)) throw new Error('Format nomor WhatsApp tidak valid.');
if (lead.consent !== 'true') throw new Error('Lead belum memberikan persetujuan WhatsApp.');
if (!Number.isInteger(lead.campaign_id) || lead.campaign_id <= 0) throw new Error(`Campaign ID untuk tahap ${stage} belum diisi.`);
if (stage === 'tes') lead.syntax = `TES#${lead.name}#${lead.city}#${lead.need}#${lead.participant_count}`;
if (stage === 'wsl1') lead.syntax = `WSL1#${lead.name}#${lead.city}#${lead.stifin_result}#${lead.learning_goal}`;
if (stage === 'promotor') lead.syntax = `PROMOTOR#${lead.name}#${lead.city}#${lead.profession}#${lead.stifin_status}#${lead.wsl_status}`;
return [{ json: lead }];
